import{_ as r,C as d,o as s,c as i,j as e,a as o,E as a,ag as c}from"./chunks/framework.CEtICT8r.js";const q=JSON.parse('{"title":"📝 OJ 题目一键转 Markdown","description":"","frontmatter":{"aside":false},"headers":[],"relativePath":"oj-extractor/index.md","filePath":"oj-extractor/index.md","lastUpdated":null}'),h={name:"oj-extractor/index.md"},p={class:"download-box"};function g(u,t,b,m,k,x){const n=d("BackLink"),l=d("DownloadCard");return s(),i("div",null,[t[0]||(t[0]=e("h1",{id:"📝-oj-题目一键转-markdown",tabindex:"-1"},[o("📝 OJ 题目一键转 Markdown "),e("a",{class:"header-anchor",href:"#📝-oj-题目一键转-markdown","aria-label":'Permalink to "📝 OJ 题目一键转 Markdown"'},"​")],-1)),t[1]||(t[1]=e("blockquote",null,[e("p",null,[o("在 Edge 中打开题目，一键抓取原始 Markdown，自动在 VSCode 中创建 "),e("code",null,"题目名.md"),o("。")])],-1)),a(n,{to:"/all/",label:"返回工具列表"}),t[2]||(t[2]=e("p",null,[o("一个由两个扩展组成的配套工具："),e("strong",null,"Edge 扩展"),o("负责拦截 OJ 题目页的 API 响应、提取题目原始 Markdown；"),e("strong",null,"VSCode 扩展"),o("负责接收数据、在当前工作区自动创建并打开 "),e("code",null,"题目名.md"),o("。两者通过本机 WebSocket（端口 8765）通信，"),e("strong",null,"所有数据都在你本地流转，不会上传到任何服务器"),o("。")],-1)),t[3]||(t[3]=e("h2",{id:"📥-下载",tabindex:"-1"},[o("📥 下载 "),e("a",{class:"header-anchor",href:"#📥-下载","aria-label":'Permalink to "📥 下载"'},"​")],-1)),e("div",p,[a(l,{platform:"Edge 扩展",file:"oj-edge-extension-v1.0.0.zip",note:"解压后「加载解压缩的扩展」，约 4 KB",href:"/downloads/oj-edge-extension-v1.0.0.zip"}),a(l,{platform:"VSCode 扩展",file:"oj-file-creator-1.0.0.vsix",note:"在 VSCode 中「从 VSIX 安装」，约 45 KB",href:"/downloads/oj-file-creator-1.0.0.vsix"})]),t[4]||(t[4]=c(`<blockquote><p>如果下载按钮点不开，请先确认安装包已经放进网站仓库的 <code>sources/tools/public/downloads/</code> 目录。</p></blockquote><h2 id="📋-基本信息" tabindex="-1">📋 基本信息 <a class="header-anchor" href="#📋-基本信息" aria-label="Permalink to &quot;📋 基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>适用 OJ 平台</td><td>实验舱 OJ（<code>oj.shiyancang.cn</code>）</td></tr><tr><td>适用浏览器</td><td>Microsoft Edge（Chromium 内核）</td></tr><tr><td>适用编辑器</td><td>Visual Studio Code 1.85 及以上</td></tr><tr><td>通信方式</td><td>本机 WebSocket，<code>127.0.0.1:8765</code></td></tr><tr><td>当前版本</td><td>v1.0.0</td></tr><tr><td>更新日期</td><td>2026-10-05</td></tr></tbody></table><h2 id="✨-主要特点" tabindex="-1">✨ 主要特点 <a class="header-anchor" href="#✨-主要特点" aria-label="Permalink to &quot;✨ 主要特点&quot;">​</a></h2><ul><li><strong>一键抓取</strong>：点一下浏览器图标，题目原文直接进 VSCode。</li><li><strong>原始 Markdown</strong>：不是渲染后的 HTML，公式、代码块、表格全部保留原样。</li><li><strong>本地通信</strong>：WebSocket 绑定在 <code>127.0.0.1</code>，不暴露到局域网、不上传云端。</li><li><strong>免手动复制</strong>：告别从网页里一点点粘贴公式和代码的麻烦。</li><li><strong>自动命名</strong>：文件以题目名称命名，方便按题号或题目名整理归档。</li><li><strong>手动触发</strong>：只有你点图标时才创建文件，浏览题目不会产生垃圾文件。</li></ul><h2 id="🛠️-安装教程" tabindex="-1">🛠️ 安装教程 <a class="header-anchor" href="#🛠️-安装教程" aria-label="Permalink to &quot;🛠️ 安装教程&quot;">​</a></h2><h3 id="step-1-·-安装-vscode-扩展" tabindex="-1">Step 1 · 安装 VSCode 扩展 <a class="header-anchor" href="#step-1-·-安装-vscode-扩展" aria-label="Permalink to &quot;Step 1 · 安装 VSCode 扩展&quot;">​</a></h3><ol><li>下载 <code>oj-file-creator-1.0.0.vsix</code> 文件。</li><li>打开 VSCode，点击左侧 <strong>扩展</strong> 图标（方块图标）。</li><li>点击扩展面板右上角的 <code>...</code> → 选择 <strong>从 VSIX 安装...</strong>。</li><li>选择刚才下载的 <code>.vsix</code> 文件。</li><li>安装完成后 <strong>重启 VSCode</strong>。</li><li>重启后右下角应弹出通知：<code>OJ服务器已启动 (端口 8765)</code>。</li></ol><blockquote><p>⚠️ 如果没弹出通知，请检查是否已打开一个文件夹作为工作区。</p></blockquote><h3 id="step-2-·-安装-edge-扩展" tabindex="-1">Step 2 · 安装 Edge 扩展 <a class="header-anchor" href="#step-2-·-安装-edge-扩展" aria-label="Permalink to &quot;Step 2 · 安装 Edge 扩展&quot;">​</a></h3><ol><li>下载 <code>oj-edge-extension-v1.0.0.zip</code> 文件。</li><li><strong>解压到一个固定文件夹</strong>（不要删除，扩展会一直从这里加载）。</li><li>打开 Edge，地址栏输入 <code>edge://extensions/</code> 回车。</li><li>打开左下角的 <strong>开发人员模式</strong> 开关。</li><li>点击 <strong>加载解压缩的扩展</strong> 按钮。</li><li>选择刚才解压出来的文件夹（确保里面能看到 <code>manifest.json</code>）。</li><li>加载成功后，列表里出现 <strong>OJ Problem Extractor</strong>。</li><li>建议点击浏览器右上角的拼图图标，把它 <strong>固定到工具栏</strong>，方便使用。</li></ol><blockquote><p>⚠️ Edge 可能提示「此扩展程序可能不安全」，这是因为扩展未经商店签名，属于正常现象，选择「保留」即可。</p></blockquote><h3 id="step-3-·-开始使用" tabindex="-1">Step 3 · 开始使用 <a class="header-anchor" href="#step-3-·-开始使用" aria-label="Permalink to &quot;Step 3 · 开始使用&quot;">​</a></h3><ol><li>确保 VSCode <strong>已打开一个文件夹</strong>（用于存放题目的工作区）。</li><li>在 Edge 中打开 OJ 的题目页面。</li><li>点击浏览器工具栏上的扩展图标。</li><li>切回 VSCode，题目文件会自动创建并打开。</li></ol><h2 id="🎬-使用流程" tabindex="-1">🎬 使用流程 <a class="header-anchor" href="#🎬-使用流程" aria-label="Permalink to &quot;🎬 使用流程&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>打开 OJ 题目页</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>自动缓存题目数据（不创建文件）</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>点击 Edge 扩展图标</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>VSCode 自动创建并打开 题目名.md</span></span></code></pre></div><h2 id="🔒-权限说明" tabindex="-1">🔒 权限说明 <a class="header-anchor" href="#🔒-权限说明" aria-label="Permalink to &quot;🔒 权限说明&quot;">​</a></h2><p><strong>Edge 扩展请求的权限</strong></p><table tabindex="0"><thead><tr><th>权限</th><th>用途</th></tr></thead><tbody><tr><td><code>webRequest</code></td><td>拦截 OJ 页面的网络请求</td></tr><tr><td><code>storage</code></td><td>临时缓存最近一次抓取的数据</td></tr><tr><td><code>host_permissions: &lt;all_urls&gt;</code></td><td>用于在所有页面注入拦截脚本</td></tr></tbody></table><p><strong>VSCode 扩展</strong></p><ul><li>仅监听本机 <code>127.0.0.1:8765</code> 端口。</li><li>只在你指定的工作区文件夹中创建 <code>.md</code> 文件。</li></ul><h2 id="📝-更新日志" tabindex="-1">📝 更新日志 <a class="header-anchor" href="#📝-更新日志" aria-label="Permalink to &quot;📝 更新日志&quot;">​</a></h2><h3 id="v1-0-0-2026-10-05" tabindex="-1">v1.0.0（2026-10-05） <a class="header-anchor" href="#v1-0-0-2026-10-05" aria-label="Permalink to &quot;v1.0.0（2026-10-05）&quot;">​</a></h3><ul><li>首次发布。</li><li>支持实验舱 OJ 题目抓取。</li><li>支持 Edge + VSCode 本地通信。</li><li>支持手动点击触发（避免误创建文件）。</li></ul><h2 id="❓-遇到问题" tabindex="-1">❓ 遇到问题 <a class="header-anchor" href="#❓-遇到问题" aria-label="Permalink to &quot;❓ 遇到问题&quot;">​</a></h2><p>安装步骤、端口占用、文件创建失败等问题，见 <strong><a href="/tools/oj-extractor/faq.html">安装与常见问题</a></strong>。</p><h2 id="📄-许可" tabindex="-1">📄 许可 <a class="header-anchor" href="#📄-许可" aria-label="Permalink to &quot;📄 许可&quot;">​</a></h2><p>本项目仅供个人学习使用，请遵守目标 OJ 平台的使用条款。</p>`,28))])}const S=r(h,[["render",g]]);export{q as __pageData,S as default};
